INSERT INTO `dbxdb`.`emailtemplates` (`id`, `TemplateName`, `TemplateText`, `Subject`, `SenderName`, `SenderEmail`) VALUES ('225', 'emailTempleteFDSTP', '<tbody> <tr> <td style=\"padding:0 0 15pt 0;\"> <div align=\"center\"> <table border=\"0\" cellspacing=\"0\" cellpadding=\"0\" style=\"width:100%;\"> <tbody> <tr> <td style=\"padding:0 0 15pt 0;\"> <p align=\"center\" style=\"font-size:12pt;font-family:Aptos,sans-serif;text-align:center;margin:0;\"> <img data-imagetype=\"External\" src=\"https://ib1.himalayanbank.com/Public/client/emailBrand.png\" border=\"0\" id=\"x__x0000_i1025\" style=\"width:390.99pt;height:72.99pt;\"> </p> </td> </tr> </tbody> </table> </div> </td> </tr> <tr> <l>Dear %customerName%,</l> </br> </br> <l>We are pleased to inform you that your Fixed Deposit (FD) request has been successfully processed.</l> </br> </br> <l></l> Here are the details of your newly created Fixed Deposit:</l> </br> <ul> <li> <td><b>Request ID:</b> %requestId%</td> </li> <li> <td><b>Deposit Product Name:</b> %productName%</td> </li> <li> <td><b>Fixed Deposit Amount:</b> %amount%</td> </li> <li> <td><b>Interest Rate:</b> %intrest%</td> </li> <li> <td><b>Tenure:</b> %tenure%</td> </li> <li> <td><b>Start Date:</b> %startDate%</td> </li> <li> <td><b>Maturity Date:</b> %maturityDate%</td> </li> <li> <td><b>FD Account Number:</b> %FDAccountNumber%</td> </li> </ul> </br> <l>The interest on your FD will be credited as per the terms of your agreement.</l> </br> </br> <l>Should you have any questions or require further assistance, please feel free to reach out to us at %FDCustomerCareNumber%.</l> </br></br> <l>Thank you for choosing HBL. We look forward to continuing to serve your banking needs.</l> </br></br> <l>Best Regards,</l> </br> <l>Himalayan Bank Limited.</l> </br> </tr> </tbody>', 'Confirmation of Fixed Deposit Request :', 'himalayanbank', 'ibanking@himalayanbank.com');
INSERT INTO `dbxdb`.`emailtemplates` (`id`, `TemplateName`, `TemplateText`, `Subject`, `SenderName`, `SenderEmail`) VALUES ('226', 'emailTempleteFDNSTP', '<tbody> <tr> <td style=\"padding:0 0 15pt 0;\"> <div align=\"center\"> <table border=\"0\" cellspacing=\"0\" cellpadding=\"0\" style=\"width:100%;\"> <tbody> <tr> <td style=\"padding:0 0 15pt 0;\"> <p align=\"center\" style=\"font-size:12pt;font-family:Aptos,sans-serif;text-align:center;margin:0;\"> <img data-imagetype=\"External\" src=\"https://ib1.himalayanbank.com/Public/client/emailBrand.png\" border=\"0\" id=\"x__x0000_i1025\" style=\"width:390.99pt;height:72.99pt;\"> </p> </td> </tr> </tbody> </table> </div> </td> </tr> <tr> <l>Dear %customerName%,</l> </br> </br> <l>Thank you for choosing HBL. We would like to acknowledge the receipt of your request for a Himal Remit Fixed Deposit (FD).</l> </br> </br> <l></l> We are currently processing your request and will update you on the status shortly. Below are the details of the Fixed Deposit request we have received:</l> </br> <ul> <li> <td><b>Request ID:</b> %requestId%</td> </li> <li> <td><b>Request Date:</b> %requestDate%</td> </li> <li> <td><b>Fixed Deposit Amount:</b> %amount%</td> </li> <li> <td><b>Tenure:</b> %tenure%</td> </li> <li> <td><b>Interest Rate:</b> %intrest%</td> </li> </ul> </br> <l>If you have any further queries or need assistance, please feel free to contact us at %FDCustomerCareNumber%.</l> </br></br> <l>Thank you for choosing HBL. We look forward to continuing to serve your banking needs.</l> </br></br> <l>We appreciate your trust in us, and we look forward to serving you further.</l> </br></br> <l>Best Regards,</l> </br> <l>Himalayan Bank Limited.</l> </br> </tr> </tbody>', 'Acknowledgment of Fixed Deposit Request :', 'himalayanbank', 'ibanking@himalayanbank.com');
